css:
.fx-hund .btn{display:inline-flex;align-items:center;justify-content:center;gap:.5em;padding:.9em 1.5em;border-radius:var(--radius);font:700 .95em var(--font-body);text-decoration:none;border:1.5px solid var(--primary);background:var(--primary);color:var(--on-primary);cursor:pointer;transition:transform calc(.25s/var(--speed)),box-shadow calc(.25s/var(--speed))}
.fx-hund .btn:hover{transform:translateY(-2px);box-shadow:0 12px 24px -14px var(--primary)}
.fx-hund .btn.ghost{background:transparent;color:var(--primary)}
.fx-hund .btn:focus-visible{outline:2px solid var(--accent);outline-offset:3px}
.fx-hund{background:var(--surface);display:flex;flex-direction:column}
.fx-hund .hd{display:flex;align-items:center;justify-content:space-between;gap:1.5em;padding:1.5em max(5vw,1.25em);border-bottom:1px solid var(--border)}
.fx-hund .logo{font:600 1.5em var(--font-heading);color:var(--text);text-decoration:none;letter-spacing:-.02em}.fx-hund .logo span{color:var(--accent)}
.fx-hund nav{display:flex;gap:2.2em}
.fx-hund nav a{position:relative;padding:.4em 0;color:var(--text);text-decoration:none;font-weight:600;font-size:.95em}
.fx-hund nav a::after{content:"";position:absolute;left:0;right:0;bottom:0;height:2px;background:var(--accent);transform:scaleX(0);transform-origin:right;transition:transform calc(.4s/var(--speed)) cubic-bezier(.7,0,.2,1)}
.fx-hund nav a:hover::after,.fx-hund nav a:focus-visible::after{transform:scaleX(1);transform-origin:left}
.fx-hund nav a[aria-current]::after{transform:scaleX(1);background:var(--primary)}
.fx-hund nav a:focus-visible,.fx-hund .logo:focus-visible{outline:2px solid var(--accent);outline-offset:4px;border-radius:3px}
.fx-hund .btn{padding:.65em 1.2em}
.fx-hund .main{flex:1;display:grid;align-content:center;gap:1.2em;width:min(900px,100%);margin:0 auto;padding:3em 1.25em 5em}
.fx-hund .main h1{font-size:clamp(2.2em,5.4vw,4em);line-height:1.1;max-width:15em}
.fx-hund .main p{font-size:1.15em;opacity:.78;max-width:42ch;line-height:1.7}
.fx-hund .main p a{color:var(--text);text-decoration:none;background:linear-gradient(var(--accent),var(--accent)) 100% 100%/0 2px no-repeat;padding-bottom:.1em;border-bottom:2px solid color-mix(in srgb,var(--text) 22%,transparent);transition:background-size calc(.4s/var(--speed)) ease}
.fx-hund .main p a:hover,.fx-hund .main p a:focus-visible{background-position:0 100%;background-size:100% 2px}
@media(max-width:700px){.fx-hund .hd{flex-wrap:wrap;gap:.8em 1em}.fx-hund nav{order:3;width:100%;gap:1.4em;overflow-x:auto}.fx-hund .btn{margin-left:auto}}
@media(prefers-reduced-motion:reduce){.fx-hund nav a::after,.fx-hund .main p a{transition:none}}
/* touch: :hover mirrored as .is-tap */
.fx-hund .btn.is-tap{transform:translateY(-2px);box-shadow:0 12px 24px -14px var(--primary)}
.fx-hund nav a.is-tap::after{transform:scaleX(1);transform-origin:left}
.fx-hund .main p a.is-tap{background-position:0 100%;background-size:100% 2px}
